  const recharge=d.action==='recharge'&&(panelOrg||personalBilling?.payments_enabled)?`<a class="overview-primary" href="${panelOrg?'#billing/organization/'+esc(panelOrg.organization.id):'#billing/personal'}">${ico('server')} 充值</a>`:'';
  const hero=`<section class="overview-hero"><div class="overview-balance"><span>${d.title}</span><strong>${d.balance===null?'未开通':'¥'+(Math.floor(d.balance*100)/100).toFixed(2)}</strong><small>${left===null?d.note:`按近 7 天消费，预计可用 ${left.toLocaleString('zh-CN')} 天 · ${d.note}`}</small></div><div class="overview-figures">${d.figures.map(([k,v])=>`<div><span>${k}</span><b>${v}</b></div>`).join('')}</div>${recharge}</section>`;
