  const credit=creditActive(),base=credit?employeeCredit.base_url:(!panelOrg&&personalPilot?.enabled?personalPilot.base_url:null),keyCount=credit?(employeeCredit.keys||[]).filter(k=>!k.revoked_at).length:(!panelOrg&&personalPilot?.enabled?(personalPilot.keys||[]).filter(k=>!k.revoked_at).length:0),sampleModel=credit?employeeCredit.model_ids?.[0]:(!panelOrg?personalPilot?.model_ids?.[0]:null);
  const sample=base&&sampleModel?`curl ${base}/chat/completions -H "Authorization: Bearer 你的Key" -H "Content-Type: application/json" -d '{"model":"${sampleModel}","messages":[{"role":"user","content":"你好"}]}'`:'';
  const connect=`<section class="personal-pilot-log overview-connect"><div class="personal-section-title"><h2>快速接入</h2></div>${base?`<div class="overview-row"><div><small>接入地址</small><code>${esc(base)}</code></div><button type="button" data-live="copy-text" data-text="${esc(base)}">复制</button></div><div class="overview-row"><div><small>我的 Key</small><b>${keyCount} 枚有效</b></div>${tabLink('keys',keyCount?'管理':'生成')}</div><div class="overview-row"><div><small>调用示例</small><code class="overview-sample">${esc(sample)}</code></div><button type="button" data-live="copy-text" data-text="${esc(sample)}">复制</button></div>`:`<p class="personal-model-empty">${employeeCredit?.enabled&&!panelOrg?`你的公司额度在 <a href="#organization/${esc(employeeCredit.organization_id)}/overview">${esc(employeeCredit.organization_name)}</a> 空间使用。`:'当前账号尚未开通调用。'}</p>`}</section>`;
  const catalog=personalCatalog(),inUse=catalog.filter(m=>d.used.includes(m.id)),shown=(inUse.length?inUse:catalog).slice(0,6);
  const models=`<section class="personal-pilot-log"><div class="personal-section-title"><h2>${inUse.length?'我在用的模型':'可用模型'}</h2>${tabLink('models','查看全部')}</div><div class="personal-table-wrap"><table><thead><tr><th>模型</th><th>状态</th><th>延迟</th><th>输入 / 输出（¥/百万）</th></tr></thead><tbody>${shown.map(m=>{const x=personalModelMeasurement(m.id),r=personalBaseRate(m);return `<tr><td><b>${esc(m.name)}</b><small>${esc(m.upstreamId)}</small></td><td><span class="personal-status ${x.tone}">${x.status}</span></td><td>${x.latency}</td><td>${personalPrice(r.miss)} / ${personalPrice(r.output)}</td></tr>`;}).join('')||'<tr><td colspan="4" class="personal-model-empty">暂无模型。</td></tr>'}</tbody></table></div></section>`;
